import Ajax from"core/ajax";const randomKey=()=>Array.from(crypto.getRandomValues(new Uint8Array(24))).map(v=>v.toString(16).padStart(2,"0")).join("");const parseYouTubeId=url=>{try{const u=new URL(url);if(u.hostname.includes("youtu.be"))return u.pathname.slice(1);if(u.searchParams.get("v"))return u.searchParams.get("v");const m=u.pathname.match(/\/(embed|shorts)\/([^/?]+)/);return m?m[2]:""}catch(e){return""}};const parseVimeoId=url=>{const m=String(url).match(/vimeo\.com\/(?:video\/)?(\d+)/);return m?m[1]:""};const renderTimeline=(el,segments,duration)=>{el.replaceChildren();if(!duration)return;segments.forEach(s=>{const span=document.createElement("span");span.style.left=100*s[0]/duration+"%";span.style.width=100*(s[1]-s[0])/duration+"%";el.append(span)})};const updateUI=(root,data,duration)=>{root.querySelector('[data-region="video-percent"]').textContent=Number(data.percent).toFixed(2)+"%";root.querySelector('[data-region="video-bar"]').style.width=data.percent+"%";document.querySelector('[data-region="overall-percent"]').textContent=Number(data.overallpercent).toFixed(2)+"%";document.querySelector('[data-region="overall-bar"]').style.width=data.overallpercent+"%";const listbar=document.querySelector('[data-video-bar="'+root.dataset.videoid+'"]');if(listbar)listbar.style.width=data.percent+"%";try{renderTimeline(root.querySelector('[data-region="timeline"]'),JSON.parse(data.segments||"[]"),duration)}catch(e){}};const sender=root=>{let seq=0,sessionkey=randomKey(),pendingStart=null,lastPosition=0,duration=0,rate=1;const send=(position,force=false)=>{if(!duration||pendingStart===null){lastPosition=position;if(force)pendingStart=position;return Promise.resolve()}const start=pendingStart,end=Math.max(start,position);pendingStart=position;lastPosition=position;seq++;return Ajax.call([{methodname:"mod_videoplaylist_update_progress",args:{cmid:Number(root.dataset.cmid),videoid:Number(root.dataset.videoid),currentposition:position,duration:duration,segmentstart:start,segmentend:end,playbackrate:rate,sequence:seq,sessionkey:sessionkey}}])[0].then(data=>updateUI(root,data,duration)).catch(()=>{})};return{setDuration:v=>duration=v,setRate:v=>rate=v||1,start:p=>{pendingStart=p;lastPosition=p},tick:p=>{if(pendingStart===null)pendingStart=p;if(Math.abs(p-lastPosition)>=5){send(p)}},pause:p=>send(p,true),seek:(from,to,allowed,max)=>{if(!allowed&&to>max+3)return max;pendingStart=to;lastPosition=to;return to},resume:()=>Number(root.dataset.lastposition||0)}};const html5=(root,track)=>{const video=document.createElement("video");video.controls=true;video.preload="metadata";video.src=root.dataset.src;root.querySelector('[data-region="player"]').append(video);let maxSeen=track.resume();video.addEventListener("loadedmetadata",()=>{track.setDuration(video.duration);if(track.resume()>0)video.currentTime=Math.min(track.resume(),video.duration-1);try{renderTimeline(root.querySelector('[data-region="timeline"]'),JSON.parse(root.dataset.segments||"[]"),video.duration)}catch(e){}});video.addEventListener("play",()=>track.start(video.currentTime));video.addEventListener("timeupdate",()=>{maxSeen=Math.max(maxSeen,video.currentTime);track.setRate(video.playbackRate);track.tick(video.currentTime)});video.addEventListener("pause",()=>track.pause(video.currentTime));video.addEventListener("ended",()=>track.pause(video.duration));video.addEventListener("seeking",()=>{const target=track.seek(maxSeen,video.currentTime,root.dataset.allowseek==="1",maxSeen);if(Math.abs(target-video.currentTime)>1)video.currentTime=target})};const youtube=(root,track)=>{const id=parseYouTubeId(root.dataset.src);if(!id){root.querySelector('[data-region="player"]').textContent="Invalid YouTube URL";return}const host=document.createElement("div");root.querySelector('[data-region="player"]').append(host);const ready=()=>new Promise(resolve=>{if(window.YT&&window.YT.Player)return resolve();const prev=window.onYouTubeIframeAPIReady;window.onYouTubeIframeAPIReady=()=>{if(prev)prev();resolve()};if(!document.querySelector('script[src*="youtube.com/iframe_api"]')){const s=document.createElement("script");s.src="https://www.youtube.com/iframe_api";document.head.append(s)}});ready().then(()=>{let timer=null;const p=new window.YT.Player(host,{videoId:id,events:{onReady:e=>{track.setDuration(e.target.getDuration());if(track.resume()>0)e.target.seekTo(track.resume(),true)},onStateChange:e=>{if(e.data===window.YT.PlayerState.PLAYING){track.start(p.getCurrentTime());timer=setInterval(()=>{track.setRate(p.getPlaybackRate());track.tick(p.getCurrentTime())},1e3)}else{if(timer){clearInterval(timer);timer=null}if(e.data===window.YT.PlayerState.PAUSED||e.data===window.YT.PlayerState.ENDED)track.pause(p.getCurrentTime())}}}})})};const vimeo=(root,track)=>{const id=parseVimeoId(root.dataset.src);if(!id){root.querySelector('[data-region="player"]').textContent="Invalid Vimeo URL";return}const frame=document.createElement("iframe");frame.src="https://player.vimeo.com/video/"+id+"?api=1";frame.allow="autoplay; fullscreen; picture-in-picture";root.querySelector('[data-region="player"]').append(frame);const load=()=>new Promise(resolve=>{if(window.Vimeo&&window.Vimeo.Player)return resolve();const s=document.createElement("script");s.src="https://player.vimeo.com/api/player.js";s.onload=resolve;document.head.append(s)});load().then(()=>{const p=new window.Vimeo.Player(frame);p.getDuration().then(d=>{track.setDuration(d);if(track.resume()>0)p.setCurrentTime(track.resume())});p.on("play",d=>track.start(d.seconds));p.on("timeupdate",d=>track.tick(d.seconds));p.on("pause",d=>track.pause(d.seconds));p.on("ended",d=>track.pause(d.seconds));p.on("playbackratechange",d=>track.setRate(d.playbackRate))})};export const init=()=>document.querySelectorAll(".videoplaylist-player").forEach(root=>{const track=sender(root);if(root.dataset.source==="youtube")youtube(root,track);else if(root.dataset.source==="vimeo")vimeo(root,track);else html5(root,track)});